import{_ as i,a as e,b as t,c as o,d as r}from"./chunks/CAL20.BDesHKIj.js";import{_ as l,o as n,c as s,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"Risoluzione problemi","description":"","frontmatter":{"source_hash":"54556a9422","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/calibrate/troubleshoot.md","filePath":"it/calibrate/troubleshoot.md"}'),d={name:"it/calibrate/troubleshoot.md"};function p(b,a,m,h,u,z){return n(),s("div",null,[...a[0]||(a[0]=[c('<h3 id="native-algorithm" tabindex="-1">Algoritmo nativo <a class="header-anchor" href="#native-algorithm" aria-label="Permalink to &quot;Algoritmo nativo {#native-algorithm}&quot;">​</a></h3><p>Se usi xDrip con l&#39;algoritmo nativo di un G6, G7, 1, 1+ o Stelo, vedi <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">qui</a>.</p><h3 id="xdrip-algorithm" tabindex="-1">Algoritmo di xDrip <a class="header-anchor" href="#xdrip-algorithm" aria-label="Permalink to &quot;Algoritmo di xDrip {#xdrip-algorithm}&quot;">​</a></h3><p>Attiva le <a href="./../use/lesscommon.html#show-data-tables">tabelle dati</a> per avere più informazioni.</p><h4 id="no-data-after-initial-calibration" tabindex="-1">Nessun dato dopo la calibrazione iniziale <a class="header-anchor" href="#no-data-after-initial-calibration" aria-label="Permalink to &quot;Nessun dato dopo la calibrazione iniziale {#no-data-after-initial-calibration}&quot;">​</a></h4><img src="'+i+'" style="zoom:75%;"><p>Se hai verificato di avere la connessione con il sensore/bridge e dopo la calibrazione iniziale non compare alcun dato, potrebbe essere perché stai calibrando troppo in alto e l&#39;intercetta calcolata supera il limite di sicurezza. <a href="./calibrate.html#reset-all-calibrations">Azzera</a> tutte le calibrazioni e riprova con glicemia stabile nella parte bassa dell&#39;intervallo.</p><h4 id="no-data-after-adding-a-new-calibration" tabindex="-1">Nessun dato dopo aver aggiunto una nuova calibrazione <a class="header-anchor" href="#no-data-after-adding-a-new-calibration" aria-label="Permalink to &quot;Nessun dato dopo aver aggiunto una nuova calibrazione {#no-data-after-adding-a-new-calibration}&quot;">​</a></h4><img src="'+e+'" style="zoom:75%;"><p>Probabilmente hai portato le calibrazioni oltre i limiti di sicurezza. Controlla la Tabella dati di calibrazione e, se necessario, <a href="./calibrate.html#disable-a-calibration">disattiva</a> la calibrazione responsabile.</p><p>Un sensore che richiede un&#39;intercetta positiva elevata potrebbe non essere sicuro. Se ritieni che il sensore sia ancora affidabile, <a href="./calibrate.html#reset-all-calibrations">azzera</a> tutte le calibrazioni e riprova con glicemia stabile nella parte bassa dell&#39;intervallo.</p><h4 id="new-calibration-is-ignored" tabindex="-1">La nuova calibrazione viene ignorata <a class="header-anchor" href="#new-calibration-is-ignored" aria-label="Permalink to &quot;La nuova calibrazione viene ignorata {#new-calibration-is-ignored}&quot;">​</a></h4><img src="'+t+'" style="zoom:75%;"><p>Controlla la Tabella dati di calibrazione: molto probabilmente vedrai le tue calibrazioni in rosso, perché sono disattivate per ragioni di sicurezza.</p><p>Molto probabilmente il sensore non è più affidabile. Se ritieni che lo sia, <a href="./calibrate.html#reset-all-calibrations">azzera</a> tutte le calibrazioni e riprova con glicemia stabile nella parte bassa dell&#39;intervallo.</p><h4 id="intercept-or-slope-above-safety-limit" tabindex="-1">Intercetta o pendenza oltre il limite di sicurezza <a class="header-anchor" href="#intercept-or-slope-above-safety-limit" aria-label="Permalink to &quot;Intercetta o pendenza oltre il limite di sicurezza {#intercept-or-slope-above-safety-limit}&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Sicurezza</p><p>I limiti che ti impediscono di calibrare sono pensati per la tua sicurezza.<br><strong>Non puoi fare affidamento su un sistema che non è in grado di rilevare l&#39;ipoglicemia.</strong></p></div><p>Apri la Tabella dati di calibrazione e controlla l&#39;ultima calibrazione.</p><img src="'+o+'" style="zoom:75%;"><div class="warning custom-block"><p class="custom-block-title">L&#39;intercetta massima consentita è 39</p><p>Un&#39;intercetta superiore a 39 mg/dl impedisce la visualizzazione della glicemia per ragioni di sicurezza.</p></div><p>I limiti di pendenza dipendono dal sensore:</p><table tabindex="0"><thead><tr><th>Sensore</th><th>Pendenza minima</th><th>Pendenza massima</th></tr></thead><tbody><tr><td>G5 o G6 con algoritmo non nativo (3 o più calibrazioni)</td><td>0,7</td><td>1,6</td></tr><tr><td>G5 o G6 con algoritmo non nativo (esattamente 2 calibrazioni)</td><td>0,75</td><td>1,5</td></tr><tr><td>Libre (sorgente di dati grezzi, Calibrazione non linear per Libre attivata)</td><td>0,5</td><td>1,6</td></tr><tr><td>Libre (sorgente di dati grezzi, pendenza fissa predefinita)</td><td>1 (fissa)</td><td>1 (fissa)</td></tr><tr><td>Libre 2 app modificata</td><td>1 (fissa)</td><td>1 (fissa)</td></tr></tbody></table><p>Poiché i limiti di sicurezza di pendenza e intercetta impediscono a xDrip di avere un&#39;intercetta troppo alta, le calibrazioni che porterebbero a questa situazione vengono ignorate.</p><p>Nell&#39;esempio qui sotto vedi che la linea arancione è quella che meglio corrisponde alle calibrazioni; tuttavia, per sicurezza xDrip userà quella rossa, perché la sua intercetta è sicura. Puoi vedere il valore dell&#39;intercetta del plugin, che rispecchia ciò che corrisponderebbe meglio alle calibrazioni.</p><img src="'+r+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 7/12/2024</em></a></p>',27)])])}const _=l(d,[["render",p]]);export{f as __pageData,_ as default};
